import os
import sys
import json
import subprocess
from typing import Dict, List, Any, Optional
from dataclasses import dataclass
import anthropic


@dataclass
class ToolCall:
    """Represents a tool call request from the model."""
    name: str
    parameters: Dict[str, Any]


class BashTool:
    """Bash command execution tool with safety checks."""

    def __init__(self, require_confirmation: bool = True):
        self.require_confirmation = require_confirmation

    def get_schema(self) -> Dict:
        """Return the tool schema for the Anthropic API."""
        return {
            "name": "run_bash",
            "description": "Execute a bash command and return the output",
            "input_schema": {
                "type": "object",
                "properties": {
                    "command": {
                        "type": "string",
                        "description": "The bash command to execute"
                    }
                },
                "required": ["command"]
            }
        }

    def execute(self, command: str) -> str:
        """Execute a bash command with optional confirmation."""
        print(f"\n🔧 Tool Request: run_bash")
        print(f"Command: {command}")

        if self.require_confirmation:
            response = input("\nExecute this command? (y/n): ").strip().lower()
            if response != 'y':
                return "Command execution cancelled by user."

        try:
            result = subprocess.run(
                command,
                shell=True,
                capture_output=True,
                text=True,
                timeout=30
            )

            output = result.stdout
            if result.stderr:
                output += f"\nSTDERR: {result.stderr}"
            if result.returncode != 0:
                output += f"\nReturn code: {result.returncode}"

            return output if output else "Command executed successfully (no output)"
        except subprocess.TimeoutExpired:
            return "Command timed out after 30 seconds"
        except Exception as e:
            return f"Error executing command: {str(e)}"


class AgentLoop:
    """Minimal agent loop with Anthropic API."""

    def __init__(self, api_key: Optional[str] = None):
        self.client = anthropic.Anthropic(
            api_key=api_key or os.environ.get("ANTHROPIC_API_KEY")
        )
        self.bash_tool = BashTool()
        self.messages: List[Dict] = []
        self.model = "claude-3-5-sonnet-20241022"

    def run(self, initial_prompt: str, max_iterations: int = 10):
        """Run the agent loop with the given prompt."""
        print(f"\n🤖 Starting agent loop (max {max_iterations} iterations)")
